window.NEO_DATA_MK2_KEY = {"set_id":2,"g":{"r_ctw_01":{"blanks":{"1":"poison","2":"must","3":"eaten","4":"is","5":"directly","6":"fangs","7":"or","8":"spines","9":"spiders","10":"and"},"kr":{"passage":["독액은 일부 동물이 사냥하거나 자신을 방어하기 위해 만들어 내는 해로운 화학물질 혼합물입니다. 먹어야 효과가 나타나는 독과 달리, 독액은 송곳니나 침, 또는 날카로운 가시를 통해 곧바로 주입됩니다. 뱀, 거미, 전갈, 그리고 일부 물고기가 저마다 다른 방식으로 이를 이용합니다. 동물이 공격하면 독액은 희생물의 신경계나 혈액, 근육을 공격할 수 있습니다. 독액은 매우 빠르게 작용하기 때문에, 먹잇감은 한번 당하면 쉽게 달아나지 못합니다. 과학자들은 이제 이 물질들을 면밀히 연구하는데, 그중 다수가 통증과 심각한 질병을 치료하는 값진 약으로 바뀔 수 있기 때문입니다."],"blanks":{"1":"'Unlike ___, which must be eaten'로 독액과 대비되는 **명사** 자리예요. '먹어야' 효과가 나면서 **poi__**로 시작하는 건 '**독(poison)**'이에요.","2":"'which ___ be eaten'로 be 앞 **조동사** 자리예요. '먹혀야 한다'는 의무를 나타내고 **mu__**로 시작하는 조동사는 '**must**'예요.","3":"'must be ___'로 수동태의 **과거분사** 자리예요. 독은 '먹혀야' 작용하니 **ea__**로 시작하는 '**eaten**'이 와요.","4":"'venom ___ injected'로 수동태를 만드는 **be동사** 자리예요. 주어 venom(단수)에 맞고 **i_**(한 글자 더)인 건 '**is**'예요.","5":"동사 injected를 꾸미는 **부사** 자리예요. '곧바로 주입된다'는 뜻이고 **dire__**로 시작하는 '**directly**'가 와요.","6":"'injected through ___'로 주입 통로가 되는 **명사**예요. **fa__**로 시작하며 뱀의 주입 기관은 '**송곳니(fangs)**'예요.","7":"'fangs, stingers, ___ sharp spines'로 나열을 잇는 **접속사** 자리예요. **o_**로 시작하는 등위접속사는 '**or**'예요.","8":"'sharp ___'로 sharp가 꾸미는 **명사**예요. **spi__**로 시작하며 '날카로운 가시'는 '**spines**'예요.","9":"'Snakes, ___, scorpions'로 나열되는 동물 **명사**예요. **spi__**로 시작하며 독을 쓰는 동물은 '**거미(spiders)**'예요(8번 spines는 가시라 자리가 달라요).","10":"'scorpions, ___ certain fish'로 마지막 나열을 잇는 **접속사** 자리예요. **a__**로 시작하는 'A, B, and C'의 '**and**'가 와요."}}},"r_dl_01":{"q":{"r_dl_01_1":{"a":0,"why":"'실시간 지도만 열면 앱이 자꾸 **crashing**한다'는 건, 앱이 갑자기 **꺼진다**는 뜻이에요. 그래서 '꺼짐(Shutting down)'이 가장 가까워요. 실제로 무언가와 부딪히는(colliding) 게 아니라 비유적인 IT 표현이에요.","wrong":[null,null,null,null],"kr":{"stem":"맥락상 \"crashing\"과 의미가 가장 가까운 것은?","opt":["꺼짐","느리게 작동함","요란하게 충돌함","광고를 띄움"]}},"r_dl_01_2":{"a":2,"why":"'**도착 시간이 완전히 틀리게 나오는 바람에** 지각할 뻔했다'가 근거예요. 그래서 '잘못된 시간이 표시돼서'가 정답이에요. 버스가 안 온 게 아니라 시간 정보가 틀린 거예요.","wrong":[null,null,null,null],"kr":{"stem":"글쓴이는 왜 수업에 지각할 뻔했나요?","opt":["버스가 오지 않아서","요금 때문에 계정이 잠겨서","잘못된 시간이 표시돼서","화면이 헷갈려서"]}}},"kr":{"passage":["저만 새 BusTracker 업데이트 때문에 고생하나요? 어제부터 실시간 지도만 열면 앱이 자꾸 튕기고, 아침 노선 알림은 아예 안 떴어요. 예전 화면이 훨씬 안정적이고 편했는데. 도착 시간이 완전히 틀리게 나오는 바람에 수업에 지각할 뻔했으니 얼른 고쳐 주세요."]}},"r_dl_02":{"q":{"r_dl_02_1":{"a":1,"why":"칭찬이 많지만 '**진도 느린 첫 2주가 지루했다**'는 뚜렷한 단점도 짚어요. 극찬 일변도가 아니라 장단점을 함께 말하니, 태도는 '**어느 정도 만족(Somewhat satisfied)**'이에요. '몹시 실망'이나 '무관심'은 정반대예요.","wrong":[null,null,null,null],"kr":{"stem":"이 강좌에 대한 글쓴이의 태도는 어떤가요?","opt":["몹시 실망함","어느 정도 만족함","완전히 무관심함","점점 더 열광함"]}},"r_dl_02_2":{"a":0,"why":"'질문을 보내면 **늘 하루 안에 답해 주셨다**'가 근거예요. 그래서 '빠른 답을 받았다(prompt replies)'가 추론돼요. 개인 과외(private tutoring)라는 말은 없어요.","wrong":[null,null,null,null],"kr":{"stem":"강좌 중 질문이 있었던 학생에 대해 무엇을 추론할 수 있나요?","opt":["빠른 답을 받았다.","개인 과외를 받았다.","영상으로 배웠다.","수업 중에만 질문할 수 있었다."]}},"r_dl_02_3":{"a":2,"why":"글쓴이가 콕 집은 단점은 '**진도가 느린 첫 2주**가 (스프레드시트를 아는 사람에겐) 겹치는 느낌'이었어요. 그래서 '초반 수업이 기초를 반복했다'가 정답이에요. 데이터셋은 무료였고 수료증은 바로 떴으니 나머지는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"글쓴이가 지적한 주된 단점은 무엇인가요?","opt":["수료증이 늦게 왔다.","데이터셋에 추가 비용이 들었다.","초반 수업이 기초를 반복했다.","일부 수업이 너무 길었다."]}}},"kr":{"passage":["해나 조","브라이트패스에서 6주짜리 '데이터 시각화 입문' 강좌를 막 끝내고, 수강을 고민하는 분들을 위해 솔직한 생각 몇 가지를 나눠 볼게요. 각 수업은 대략 90분이었고, 학생을 진심으로 아끼는 오카포 박사님은 질문을 보내면 늘 하루 안에 답해 주셨어요. 수업이 정말 직접 해 보는 방식이라, 영상만 보는 게 아니라 매주 실제로 작동하는 인터랙티브 차트를 만들었어요.","가장 좋았던 점은 연습용 데이터셋이 추가 비용 없이 포함돼 있었다는 거예요. 요즘 은근히 드문 일이죠. 유일한 단점은, 진도가 느린 첫 2주가 스프레드시트를 이미 아는 사람에겐 좀 지루하게 느껴졌다는 거예요. 그래도 지금껏 들은 온라인 강좌 중 가장 알찼고, 최종 과제를 제출하자마자 수료증이 떴어요. 실무에 바로 쓸 기술을 원한다면 충분히 값어치를 해요."]}},"r_dl_03":{"q":{"r_dl_03_1":{"a":0,"why":"","wrong":[null,null,null,null]},"r_dl_03_2":{"a":2,"why":"","wrong":[null,null,null,null]},"r_dl_03_3":{"a":3,"why":"","wrong":[null,null,null,null]}}},"r_ac_01":{"q":{"r_ac_01_1":{"a":1,"why":"'이 초기 공연은 귀족 계층의 **우아함과 절제**를 보여 주기 위한 것이었다'가 근거예요. 그래서 '귀족의 우아함과 절제를 드러내려고'가 정답이에요. 많은 이를 즐겁게 하려던 오락(amuse)이 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"지문에 따르면, 가장 초기의 궁정 발레는 무엇을 위한 것이었나요?","opt":["궁정의 많은 이를 즐겁게 하려고","귀족의 우아함과 절제를 드러내려고","귀족을 전문 무용수로 키우려고","귀족의 절제와 우아함을 막으려고"]}},"r_ac_01_2":{"a":2,"why":"'무용 교사들은 ... 정확히 가르치고 반복할 수 있도록 **움직임에 이름을 붙였다**'가 근거예요. 그래서 '동작에 이름을 붙여 전달할 수 있게 했다'가 정답이에요. 작곡(A)이나 극장 건립(B)은 무용 교사가 한 일이 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"지문은 무용 교사들이 어떻게 발레를 다듬었다고 말하나요?","opt":["각 춤에 맞춰 음악을 작곡함으로써","관객이 볼 수 있는 최초의 극장을 세움으로써","동작에 이름을 붙여 남에게 전할 수 있게 함으로써","더 긴 춤을 지어내며 이야기를 전함으로써"]}},"r_ac_01_3":{"a":3,"why":"'기술적 요구가 높아지자 아마추어 궁정인이 **숙련된 전문가로 대체되었다**'가 근거예요. 그래서 '귀족 대신 전문가에게 의존하게 됐다'가 추론돼요. 더 쉬워졌다는 B는 정반대예요.","wrong":[null,null,null,null],"kr":{"stem":"기술적 요구가 높아지면서 발레에 대해 무엇을 추론할 수 있나요?","opt":["새로운 종류의 시설이 생겨났다.","더 쉬워져 더 많은 귀족이 출 수 있었다.","다시 궁정 안에서만 공연되었다.","귀족 대신 전문가에게 의존하게 되었다."]}},"r_ac_01_4":{"a":0,"why":"'19세기에 이르러 **발레**는 고유의(its own) 용어를 갖춘 분야가 되었다'는 문장이에요. its는 바로 그 주어 '**발레(ballet)**'를 가리켜요.","wrong":[null,null,null,null],"kr":{"stem":"\"its own vocabulary\"에서 \"its\"가 가리키는 것은?","opt":["발레","19세기","훈련법","이름난 무용수들"]}},"r_ac_01_5":{"a":1,"why":"본문은 발레가 궁정 과시로 시작(A)해, 무용 교사에게 배우고(C), 1800년대엔 세련된 예술이 됐다(D)고 해요. 하지만 '**수 세기 동안 궁전 안 아마추어 공연으로 남았다**'는 건, 전문가·극장으로 옮겨 갔다는 흐름과 정반대예요. 그래서 B가 본문과 어긋나 정답(EXCEPT)이에요.","wrong":[null,null,null,null],"kr":{"stem":"지문에 따르면, 발레의 발전을 설명하는 것으로 옳지 않은 것은?","opt":["르네상스 유럽 궁정에서 궁정 과시로 시작되었다.","수 세기 동안 궁전 안 아마추어 공연으로 남았다.","일부 사람은 무용 교사에게 발레를 배웠다.","1800년대에 세련된 공연 형식이 되었다."]}}},"kr":{"passage":["발레는 대중 오락이 아니라 르네상스 유럽 궁정 안의 과시 형식으로 시작되었습니다. 화려한 궁정 축제에서 귀족들은 음악과 시, 볼거리를 결합한 정교하게 짜인 춤을 추었습니다. 이 초기 공연은 귀족 계층의 우아함과 절제를 보여 주기 위한 것이었고, 참가자들은 훈련된 전문가라기보다 궁정의 구성원인 경우가 많았습니다.","시간이 지나면서 이 예술은 더 체계적이고 까다로워졌습니다. 무용 교사들은 자세와 동작을 체계화하기 시작해, 정확히 가르치고 반복할 수 있도록 움직임에 이름을 붙였습니다. 기술적 요구가 높아지자, 무대에서 아마추어 궁정인은 점차 숙련된 전문가로 대체되었습니다. 공연은 궁전 홀에서 극장으로 옮겨 갔고, 그곳에서 돈을 낸 관객이 관람할 수 있었습니다.","안무가들은 춤을 위해 특별히 작곡된 음악에 맞추어 움직임으로 이야기를 전하는 더 긴 작품을 만들었습니다. 19세기에 이르러 발레는 고유의 용어와 훈련법, 이름난 무용수를 갖춘 고도로 세련된 분야가 되었습니다. 무용수들은 균형과 턴아웃, 무게가 없는 듯한 착각을 익히는 데 여러 해를 쏟았습니다. 한때 귀족의 궁정 오락이던 것이, 신체적 난도와 표현력 모두로 여러 나라에서 찬사받는 진지한 공연 예술로 탈바꿈했습니다."]}},"r_ctw_02":{"blanks":{"1":"carry","2":"pieces","3":"stone","4":"carving","5":"and","6":"over","7":"periods","8":"time","9":"the","10":"waves"},"kr":{"passage":["침식은 물과 바람, 얼음이 암석과 흙을 서서히 깎아 내는 과정입니다. 강은 작은 돌 조각을 하류로 실어 나르며, 오랜 세월에 걸쳐 계곡과 협곡을 깎아 냅니다. 해안을 따라서는 파도가 절벽에 부딪혀 이를 조금씩 모래로 부숩니다. 바람은 헐거운 입자를 들어 올려 멀리 떨어뜨리며 모래언덕을 빚고 단단한 표면을 매끄럽게 만듭니다. 추운 지역에서는 움직이는 얼음이 땅을 긁고 무거운 바위를 먼 거리까지 끌고 갑니다. 각각의 변화는 작지만 그 효과는 수천 년에 걸쳐 쌓입니다. 이렇게 침식은 행성 전체의 표면을 끊임없이 다시 빚어냅니다."],"blanks":{"1":"주어 Rivers 뒤 **동사** 자리예요. **ca__**로 시작하며 조각을 하류로 '실어 나른다'는 '**carry**'예요.","2":"'tiny ___ of stone'로 tiny가 꾸미는 **명사**예요. **pie__**로 시작하며 '작은 조각'은 '**pieces**'예요.","3":"'pieces of ___'로 of 뒤 **명사**예요. **st__**로 시작하며 강이 나르는 것은 '**돌(stone)**'이에요.","4":"'실어 나르며 ~한다'는 동시 동작의 **분사(-ing)** 자리예요. **car__**로 시작하며 계곡을 '깎아 낸다'는 '**carving**'이에요.","5":"'valleys ___ canyons'로 두 명사를 잇는 **접속사**예요. **a__**로 시작하는 '**and**'가 와요.","6":"'___ long periods of time'로 기간을 나타내는 **전치사**예요. **ov__**로 시작하며 '~에 걸쳐'를 뜻하는 '**over**'가 와요.","7":"'long ___ of time'로 long이 꾸미는 **명사**예요. **per__**로 시작하며 '오랜 기간'은 '**periods**'예요.","8":"'periods of ___'로 of 뒤 **명사**예요. **ti__**로 시작하며 'periods of time(오랜 세월)'의 '**time**'이에요.","9":"'Along ___ coast'로 특정 해안을 가리키는 **관사**예요. **t__**로 시작하는 정관사 '**the**'예요.","10":"'___ pound against cliffs'로 절벽에 부딪히는 주어 **명사**예요. **wa__**로 시작하며 해안에서 절벽을 치는 것은 '**파도(waves)**'예요."}}},"r_dl_04":{"q":{"r_dl_04_1":{"a":3,"why":"니나가 자리 밑에 뒀는데 오마르가 '**강의실이 지금 비어 있다**'고 했어요. 즉 물병이 **원래 둔 자리에서 사라졌다**고 추론돼요. 뒤에 안내 데스크에서 발견되지만, 자리엔 없었어요.","wrong":[null,null,null,null],"kr":{"stem":"물병에 대해 무엇을 추론할 수 있나요?","opt":["니나가 화학 실험실에 두고 왔다.","오마르가 대신 보관하고 있다.","오마르가 맡겨 두었다.","니나가 둔 자리에서 사라졌다."]}},"r_dl_04_2":{"a":1,"why":"'**5시 전에 와서 찾아가라(come by ... to pick it up)**'가 근거예요. 그래서 '가서 찾아오라(Collect it)'가 정답이에요. '5시에'가 아니라 '5시 전에'라 A는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"오마르는 니나에게 무엇을 하라고 하나요?","opt":["5시에 찾아라.","가서 찾아와라.","자리 밑을 뒤져 봐라.","새로 사라."]}}},"kr":{"passage":["니나: 화학 강의 끝나고 제 회색 물병 가져가신 분 있어요? 214호 제 자리 밑에 두고 왔어요.","오마르: 못 봤는데, 방금 지나가 보니 강의실이 지금 비어 있어요.","니나: 아 참. 안내 데스크 좀 확인해 줄래요? 분실물은 보통 거기에 둬요.","오마르: 좋은 생각이에요. 직원분이 회색 물병이 들어왔대요. 5시 전에 와서 찾아가세요.","니나: 완전 은인이에요. 지금 갈게요."]}},"r_dl_05":{"q":{"r_dl_05_1":{"a":0,"why":"광고 전체가 '이력서 검토·재작성 **서비스**'를 소개하고 가격과 포함 사항을 안내해요. 그래서 '작문 서비스를 홍보하는 것'이 목적이에요. 면접 기술을 가르치거나 소프트웨어를 파는 게 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"이 광고의 주된 목적은 무엇인가요?","opt":["작문 서비스를 홍보하려고","졸업생 취업을 도우려고","면접 기술을 가르치려고","구직 소프트웨어를 팔려고"]}},"r_dl_05_2":{"a":3,"why":"'밋밋한 나열을 성과 중심의 **sharp**한 문서로 바꾼다'는 맥락이에요. 여기서 sharp는 경사(steep)나 신맛이 아니라 '군더더기 없고 효과적인'이라는 뜻이라 '효과적인(effective)'이 가장 가까워요.","wrong":[null,null,null,null],"kr":{"stem":"지문에서 쓰인 대로 \"sharp\"와 의미가 가장 가까운 것은?","opt":["가파른","갑작스러운","신맛의","효과적인"]}},"r_dl_05_3":{"a":2,"why":"'**두 차례 수정이 추가 비용 없이 포함된다**'가 근거예요. 그래서 '두 번의 수정(Two edits)'이 정답이에요. 자기소개서는 20달러 추가라 무료가 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"추가 비용 없이 포함되는 것은 무엇인가요?","opt":["자기소개서","상담","두 번의 수정","당일 배송"]}}},"kr":{"passage":["면접까지 가자: 이력서 작성 서비스","이력서가 인상을 남길 시간은 약 6초뿐이에요. 그래서 저희 서비스는 학생과 사회 초년생이 밋밋한 경력 나열을 성과 중심의 날카로운 문서로 바꾸도록 도와요. 지원하는 직무에 맞춰 이력서를 손보고, 고용주가 가장 눈여겨보는 성과를 부각해요.","패키지","기본 패키지: 이력서 전체 검토와 재작성 45달러.","어울리는 자기소개서 추가 시 20달러 추가.","포함 사항","두 차례 수정이 추가 비용 없이 포함돼요.","대부분의 초안은 영업일 기준 3일 안에 돌려드려요.","시작하려면 현재 이력서를 hello@careerlift.co로 보내 주세요."]}},"r_ctw_03":{"blanks":{"1":"insulating","2":"usually","3":"two","4":"layers","5":"cooperate","6":"against","7":"cold","8":"undercoat","9":"warm","10":"near"},"kr":{"passage":["얼어붙은 북쪽에서 살아남는 동물은 단순히 몸을 덮는 것 이상을 하는 털에 의존합니다. 이들의 단열 털은 대개 두 겹의 층으로 이루어지는데, 두 층이 추위를 막기 위해 촘촘히 협력합니다. 빽빽한 속털은 피부 가까이에 따뜻한 공기를 가두어, 매서운 바람에도 견디는 꾸준한 단열을 제공합니다. 물을 잘 털어 내는 긴 겉털은 사나운 폭풍 속에서도 동물을 마른 상태로 유지합니다. 많은 종에서 털은 겨울 동안 하얗게 변해, 끝없는 눈밭에서 완벽한 위장이 되어 줍니다. 어떤 털은 심지어 속이 비어 있어, 공기를 추가로 가두어 온기와 편안함을 높입니다."],"blanks":{"1":"'Their ___ coats'로 coats를 꾸미는 **형용사** 자리예요. **insul__**로 시작하며 '단열하는'을 뜻하는 '**insulating**'이 와요.","2":"동사 contain을 꾸미는 **부사** 자리예요. **usu__**로 시작하며 '대개'를 뜻하는 '**usually**'가 와요.","3":"'___ separate layers'로 layers를 세는 **수사**예요. 뒤에 속털·겉털 두 종류가 나오니 **t__**로 시작하는 '**two**'가 와요.","4":"'two separate ___'로 two가 세는 **명사**예요. **lay__**로 시작하며 털의 '층'은 '**layers**'예요.","5":"관계대명사 that 뒤 **동사** 자리예요. 두 층이 '협력한다'는 뜻이고 **coop__**로 시작하는 '**cooperate**'가 와요.","6":"'cooperate tightly ___ the cold'로 '추위에 맞서'를 뜻하는 **전치사**예요. **aga__**로 시작하는 '**against**'가 와요.","7":"'against the ___'로 the 뒤 **명사**예요. **co__**로 시작하며 막아야 할 대상은 '**추위(cold)**'예요.","8":"'A dense ___'로 dense가 꾸미는 **명사**예요. **unde__**로 시작하며 피부 가까운 '속털'은 '**undercoat**'예요.","9":"'traps ___ air'로 air를 꾸미는 **형용사**예요. **wa__**로 시작하며 속털이 가두는 건 '**따뜻한(warm)**' 공기예요.","10":"'air ___ the skin'로 위치를 나타내는 **전치사**예요. **ne__**로 시작하며 '~ 가까이'를 뜻하는 '**near**'가 와요."}}},"r_ac_02":{"q":{"r_ac_02_1":{"a":1,"why":"'익숙한 생명체와 **똑같은** 기본 대사·번식을 유지하지만, 보통 단백질이라면 파괴될 환경에서 그렇게 한다'가 근거예요. 그래서 '치명적인 환경 속에서 평범한 생명 활동을 해낸다'가 정답이에요. 남다른 대사(A)가 아니라 '똑같은' 대사라 A는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"지문에 따르면, 극한생물이 주목할 만한 이유는?","opt":["다른 어떤 생물과도 다른 종류의 대사에 의존하기 때문에","그 외엔 치명적인 환경 속에서 평범한 생명 활동을 해내기 때문에","지구에서 가장 먼저 진화한 미생물이기 때문에","혹독한 서식지와 온화한 서식지를 빠르게 오가기 때문에"]}},"r_ac_02_2":{"a":2,"why":"둘째 문단은 효소의 단단한 접힘, 보호 화합물 축적처럼 **극한에서 살아남게 하는 구조적 특성들**을 설명해요. 그래서 '극한 환경 생존을 가능하게 하는 특성을 설명하는 것'이 목적이에요. 정의(B)나 의심 제기(D)가 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"둘째 문단의 목적은 무엇인가요?","opt":["극한생물이 회복력 있게 행동한다고 주장하려고","무엇이 극한생물의 자격을 만드는지 규정하려고","극한 환경에서의 생존을 가능하게 하는 특성을 설명하려고","극한생물이 파멸적 환경에서 버틸 만큼 튼튼한지 의심하려고"]}},"r_ac_02_3":{"a":3,"why":"'물을 밖으로 끌어내 ___'라는 맥락이에요. 삼투압이 세포에서 물을 빼내면 세포가 '말라 버린다'는 뜻이라, desiccate는 '**말리다(dry out)**'와 가장 가까워요.","wrong":[null,null,null,null],"kr":{"stem":"지문에서 \"desiccate\"와 의미가 가장 가까운 것은?","opt":["중독시키다","식히다","커지게 하다","말리다"]}},"r_ac_02_4":{"a":"1.2","why":"질문의 핵심은 '**짠 물의 생물이 물 손실을 어떻게 막느냐**'예요. 세 번째 문장이 '세포 안에 용질을 쌓아 **삼투압을 상쇄한다**'고 그 방법을 정확히 짚으니 정답이에요. 효소 이야기(둘째 문장)는 열에 대한 적응이라 달라요.","wrong":[null,null,null,null],"kr":{"stem":"아주 짠 물에 사는 생물이 세포에서 물이 빠져나가는 것을 어떻게 막는지 설명하는 문장을 클릭하세요.","opt":["이러한 회복력을 가능하게 하는 적응은 행동만큼이나 구조적이다.","예컨대 열을 좋아하는 종의 효소는 여분의 화학 결합으로 강화된 유난히 단단한 형태로 접혀, 보통 단백질이라면 풀릴 온도에서도 제 기능의 형태를 유지한다.","고염 수역에 사는 생물은 세포 안에 적합성 용질을 쌓아, 물을 밖으로 끌어내 말려 버릴 삼투압을 상쇄한다.","각 경우에 분자의 안정성은 매우 특수한 변화를 통해 얻어져, 그 생물은 온화한 조건에서 살지 못하는 경우가 많다."]}},"r_ac_02_5":{"a":0,"why":"이 표현은 화성 염수와 나란히 '**태양계에서 생물이 살아남을 만한 장소**'의 예로 나와요. 즉 **지구 밖에서 생명이 이어질 수 있는 곳**을 가리키죠. 그래서 A가 정답이에요. 극한생물이 그리로 이동한다(B)거나 거기 생물이 확실히 있다(D)는 말은 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"글쓴이는 왜 \"먼 위성의 얼음 덮인 바다\"를 언급하나요?","opt":["생물이 살 수 있는 지구 밖 장소를 가리키려고","극한생물이 다른 행성으로 이동할 수 있는 방법을 설명하려고","화성 생물의 구체적인 화학을 설명하려고","그런 곳에 극한생물 종이 있다고 단언하려고"]}}},"kr":{"passage":["극한생물은 한때 어떤 생명체에도 치명적이라 여겨지던 조건에서 번성하는 미생물로, 펄펄 끓는 열수 분출구나 광물로 포화된 소금 호수, 농축 산에 버금가게 부식성이 강한 산성 온천 속에서도 살아갑니다. 이들의 존재는 생물학자들이 생화학이 작동할 수 있는 물리적 한계를 다시 생각하게 만들었습니다. 이 생물들은 익숙한 생명체가 필요로 하는 것과 똑같은 기본적 대사와 번식 과정을 유지하지만, 보통의 단백질이라면 순식간에 파괴될 환경에서 그렇게 합니다.","이러한 회복력의 바탕이 되는 적응은 행동만큼이나 구조적입니다. 예컨대 열을 좋아하는 종의 효소는 여분의 화학 결합으로 강화된 유난히 단단한 형태로 접혀, 보통 단백질이라면 풀려 버릴 온도에서도 제 기능의 형태를 유지합니다. 아주 짠 물에 사는 생물은 세포 안에 보호 화합물을 쌓아, 물을 밖으로 끌어내 말려 버릴 삼투압을 상쇄합니다. 각 경우에 분자의 안정성은 매우 특수한 변화를 통해 얻어지기에, 그 생물은 오히려 온화한 조건에서는 살지 못하는 경우가 많습니다.","이 발견들의 중요성은 생물학적 진기함을 목록에 올리는 데 그치지 않습니다. 극한생물은 액체 물과 에너지원이 함께 있는 곳이라면 어디든 생명이 이어질 수 있음을 보여 주기에, 지하의 화성 염수부터 먼 위성의 얼음 덮인 바다에 이르기까지 태양계 다른 곳에서 생물이 살아남을 만한 장소에 대한 추정을 바꿔 놓았습니다. 그런 곳에 실제로 생명이 깃들어 있는지는 아직 밝혀지지 않았지만, 극한생물은 혹독함만으로 생명의 가능성을 배제할 수는 없음을 입증합니다."]}},"l_a01":{"q":{"l_a01_1":{"a":1,"why":"화자는 댄스 스튜디오의 개장 시간을 묻고 있어요. 이때, 상대방이 그 정보를 모를 경우, 직접 전화해서 알아보라는 제안은 질문에 대한 정보를 얻을 수 있는 가장 합리적인 방법이에요. 따라서 이 답변이 가장 적절해요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그의 미술 수업은 매우 인기가 많아요.","전화해서 알아보셨어요?","제 여동생이 거기서 발레를 배웠어요.","개인 레슨도 제공하나요?"]}}},"script":[{"sp":"M","text":"What time does the dance studio open?"}],"kr":{"script":"댄스 스튜디오는 몇 시에 문을 여나요?"}},"l_a02":{"q":{"l_a02_1":{"a":3,"why":"스크립트에서 '지원서를 벌써 제출했어요?'라고 지원서 제출 여부를 묻고 있어요. 정답인 '그것을 끝내려면 시간이 더 필요해요'는 지원서가 아직 완성되지 않았고, 따라서 제출되지 않았음을 나타내요. 이 답변은 지원서 제출 상태에 대한 질문에 직접적으로 응답하는 내용이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["먼저 붓에 바르세요.","회의가 곧 시작될 거예요.","아마 수업 중에 어느 시점에 할 거예요.","그것을 끝내려면 시간이 더 필요해요."]}}},"script":[{"sp":"W","text":"Have you submitted your application yet?"}],"kr":{"script":"지원서를 벌써 제출했어요?"}},"l_a03":{"q":{"l_a03_1":{"a":0,"why":"화자가 상대방이 레온 호수에서 대학교 조정팀과 함께 노 젓는 것을 봤다고 말했어요. 이는 상대방이 조정팀의 일원이며 그곳에서 연습한다는 것을 의미해요. 따라서 '저희는 항상 거기서 연습해요'라는 응답이 가장 자연스럽고 적절해요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["저희는 항상 거기서 연습해요.","그 가게는 할인을 많이 하나요?","아니요, 새 보트요.","저는 방금 종이비행기 만드는 법을 배웠어요."]}}},"script":[{"sp":"M","text":"I saw you rowing with the varsity crew team at Leon Lake."}],"kr":{"script":"레온 호수에서 당신이 대학교 조정팀과 함께 노 젓는 것을 봤어요."}},"l_a04":{"q":{"l_a04_1":{"a":2,"why":"화자가 '세미나 논문 다 쓰셨어요?'라고 물었을 때, 'Just about.'은 '거의 다 했다'는 의미로, 논문이 거의 완성되었음을 나타내는 적절한 대답이에요. 이는 논문 완성 여부에 대한 질문에 직접적으로 답하는 표현이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["매우 구체적이에요.","훨씬 더 길어요.","거의 다 했어요.","좀 어려워요."]}}},"script":[{"sp":"W","text":"Have you finished your seminar paper?"}],"kr":{"script":"세미나 논문 다 쓰셨어요?"}},"l_a05":{"q":{"l_a05_1":{"a":0,"why":"스크립트에서 \"오늘 밤 파티를 누가 주최하나요?\"라고 누가 파티를 여는지 묻고 있어요. 0번 선택지 \"마케팅 팀이 주최해요.\"는 이 질문에 직접적으로 대답하고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["마케팅 팀이 주최해요.","오늘 밤이에요.","어쩔 수 없어요.","이틀 동안 유효해요."]}}},"script":[{"sp":"M","text":"Who is hosting the party tonight?"}],"kr":{"script":"오늘 밤 파티를 누가 주최하나요?"}},"l_a06":{"q":{"l_a06_1":{"a":1,"why":"화자가 \"결국 오늘 저녁에는 시간이 안 돼요\"라고 말했어요. 이 말은 오늘 저녁에 잡혀 있던 일정을 변경해야 한다는 의미예요. 따라서, 이 상황에서 가장 적절한 응답은 다른 날로 일정을 다시 잡는 것이므로, \"그럼 내일로 일정을 잡을게요\"가 정답이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["가격이 너무 비싸서 유감이에요.","그럼 내일로 일정을 잡을게요.","산책하기에 좋은 날씨예요.","아침 교통 체증은 항상 심해요."]}}},"script":[{"sp":"W","text":"I'm not free this evening after all."}],"kr":{"script":"결국 오늘 저녁에는 시간이 안 돼요."}},"l_a07":{"q":{"l_a07_1":{"a":3,"why":"스크립트에서 '새 역사책이 재미있었는지' 묻고 있어요. 4번 선택지는 '네'라고 긍정적으로 답하며, '제가 가장 좋아하는 교수님이 쓰신 책이에요!'라고 책을 즐긴 구체적인 이유를 제시하고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["아니요, 그녀는 어제 서점에 갔어요.","그 서점은 외국어 서적을 꽤 많이 가지고 있어요.","도서관은 오후 5시까지 열려 있어요.","네, 제가 가장 좋아하는 교수님이 쓰신 책이에요!"]}}},"script":[{"sp":"M","text":"Did you enjoy the new history book?"}],"kr":{"script":"새 역사책 재미있게 읽었어요?"}},"l_a08":{"q":{"l_a08_1":{"a":2,"why":"화자가 무료 피트니스 수업에서 청자를 보지 못했다고 말했어요. 3번 선택지인 \"제 마지막 수업이 늦게 끝났어요\"는 청자가 수업에 참석하지 못한 이유를 설명해 주고 있어요. 따라서 이 답변이 가장 적절해요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["돈을 충분히 모으지 못했어요.","네, 저는 대학에서 생물학을 공부했어요.","제 마지막 수업이 늦게 끝났어요.","피트니스 수업은 유익해요."]}}},"script":[{"sp":"W","text":"I didn't see you at the free fitness class."}],"kr":{"script":"무료 피트니스 수업에서 당신을 못 봤어요."}},"l_b01":{"q":{"l_b01_1":{"a":2,"why":"대화에서 '리버사이드 파빌리온(Riverside Pavilion)'에서 피로연을 열 것이고, 그곳에서 '강이 아름답게 보인다'고 언급했어요. 이는 피로연 장소가 강가에 있음을 나타내요.","wrong":[null,null,null,null],"kr":{"stem":"결혼 피로연은 어디에서 열릴까요?","opt":["호텔에서","식당에서","강가에서","정원에서"]}},"l_b01_2":{"a":1,"why":"대화에서 '피로연 동안 연주할 지역 밴드를 예약했다'고 명확하게 말했어요. 따라서 지역 밴드가 오락거리가 될 거예요.","wrong":[null,null,null,null],"kr":{"stem":"피로연에는 어떤 종류의 오락거리가 있을까요?","opt":["DJ","지역 밴드","마술사","댄스단"]}}},"script":[{"sp":"M","text":"Have you decided on a venue for your wedding reception?"},{"sp":"W","text":"Yes, we're going to have it at the Riverside Pavilion. It has a beautiful view of the river."},{"sp":"M","text":"That sounds lovely. Are you planning to have live music?"},{"sp":"W","text":"Yes, we've booked a local band to play during the reception."},{"sp":"M","text":"Great choice. It's going to be a wonderful event."}],"kr":{"script":"결혼 피로연 장소는 정했어요? 네, 리버사이드 파빌리온에서 할 거예요. 강이 아름답게 보여요. 정말 좋겠네요. 라이브 음악도 할 계획이에요? 네, 피로연 동안 연주할 지역 밴드를 예약했어요. 좋은 선택이에요. 멋진 행사가 될 거예요."}},"l_b02":{"q":{"l_b02_1":{"a":3,"why":"남자는 여자가 미술용품점 폐점에 대해 안타까워하자, '알아요. 그래서 당신을 찾으러 온 거예요.'라고 말했어요. 이는 남자가 가게 폐점 소식을 여자에게 알려주기 위해 찾아왔음을 보여줘요.","wrong":[null,null,null,null],"kr":{"stem":"남자는 왜 여자를 찾고 있었나요?","opt":["그녀에게 미술 용품을 전달하기 위해","그녀를 쇼핑몰에 초대하기 위해","그녀에게 그림 수업을 부탁하기 위해","그녀에게 가게 폐점에 대해 알리기 위해"]}},"l_b02_2":{"a":3,"why":"여자는 '온라인으로 살 수도 있고, 10마일 떨어진 포터빌(Porterville)에 있는 가게로 갈 수도 있고요.'라고 말했어요. 그리고 '포터빌에 정기적으로 가야 할 것 같네요.'라고 덧붙이며, 다른 도시인 포터빌에서 미술 용품을 구매할 계획임을 밝혔어요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 앞으로 무엇을 할 것이라고 말하나요?","opt":["온라인 쇼핑을 더 자주 할 거예요","포터빌로 이사할 거예요","남자를 위해 그림을 그릴 거예요","다른 도시에서 미술 용품을 구매할 거예요"]}}},"script":[{"sp":"M","text":"I just heard that the art store in the mall is going out of business."},{"sp":"W","text":"Oh no! I get painting supplies for my senior art project there."},{"sp":"M","text":"I know. That's why I came looking for you. What will you do now?"},{"sp":"W","text":"Well, I have a couple of options. I could get them online or I can go to the store in Porterville ten miles away."},{"sp":"M","text":"Seems to me like you'd want to buy that kind of stuff in person."},{"sp":"W","text":"I would. It looks like I'll be making regular trips to Porterville."}],"kr":{"script":"방금 쇼핑몰에 있는 미술용품점이 문을 닫는다는 소식을 들었어요. 세상에! 제 졸업 미술 프로젝트에 필요한 그림 용품을 거기서 샀는데. 알아요. 그래서 당신을 찾으러 온 거예요. 이제 어떻게 할 거예요? 음, 몇 가지 선택지가 있어요. 온라인으로 살 수도 있고, 10마일 떨어진 포터빌(Porterville)에 있는 가게로 갈 수도 있고요. 제 생각엔 그런 물건은 직접 보고 사는 게 좋을 것 같아요. 저도 그럴 거예요. 포터빌에 정기적으로 가야 할 것 같네요."}},"l_c01":{"q":{"l_c01_1":{"a":3,"why":"스크립트에서 \"학생 행정 업무 사무실은 새로 단장한 엘름 빌딩으로 이전합니다\"라고 말하고 있어요. 이는 사무실의 위치가 바뀐다는 것을 의미해요.","wrong":[null,null,null,null],"kr":{"stem":"사무실에 대해 무엇이 바뀌나요?","opt":["정책","업무 활동","운영 시간","위치"]}},"l_c01_2":{"a":3,"why":"스크립트에서 \"새로운 장소에는 현대적인 카페가 들어설 예정이며, 이곳에서는 고급 커피, 말차 라떼, 그리고 모든 종류의 차를 제공할 것입니다\"라고 언급했어요. 화자는 이 새로운 카페가 행정 업무를 \"기대할 만한 일로 만들기를 바랍니다\"라고 말하며 학생들이 좋아할 것이라고 암시하고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 학생들이 무엇을 좋아할 것이라고 생각하나요?","opt":["필요한 서류 작업량 감소","성적 증명서 사본 발급 절차 변경","재정 지원 증가","음료를 마실 수 있는 새로운 장소"]}}},"script":[{"sp":"M","text":"Starting next Monday, the office for student administrative activities will relocate to the newly renovated Elm Building. Office hours remain 9 a.m. to 5 p.m. Monday through Friday. The new location will have a modern cafe, which will offer premium coffee, matchellates, and all kinds of tea. We hope this new feature will make administrative tasks like updating your financial aid paperwork or requesting transcript copies, something that you might even look forward to."}],"kr":{"script":"다음 주 월요일부터 학생 행정 업무 사무실은 새로 단장한 엘름 빌딩으로 이전합니다. 업무 시간은 월요일부터 금요일까지 오전 9시부터 오후 5시까지로 변동 없습니다. 새로운 장소에는 현대적인 카페가 들어설 예정이며, 이곳에서는 고급 커피, 말차 라떼, 그리고 모든 종류의 차를 제공할 것입니다. 저희는 이 새로운 시설이 재정 지원 서류 업데이트나 성적 증명서 사본 요청과 같은 행정 업무를 여러분이 심지어 기대할 만한 일로 만들기를 바랍니다."}},"l_c02":{"q":{"l_c02_1":{"a":0,"why":"화자는 \"예상보다 많은 인원이 참석할 것으로 예상되어 이제 교내 극장에서 열릴 예정입니다\"라고 말했어요. 이는 예상보다 많은 참석 인원 때문에 시상식 장소가 변경되었다는 필요한 변경 사항을 설명하는 거예요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 많은 참석 인원을 언급하나요?","opt":["필요한 변경 사항을 설명하기 위해","의견을 뒷받침하기 위해","제한된 주차 공간에 대해 경고하기 위해","학생들이 행사에 참석하도록 독려하기 위해"]}},"l_c02_2":{"a":1,"why":"스크립트에서 \"저희는 여전히 안내원(usher)으로 봉사하고... 자원봉사자를 찾고 있습니다. 관심 있으신 분은 가능한 한 빨리 매튜스 학장님께 연락해 주십시오\"라고 말했어요. 이는 자원봉사를 통해 도움을 제공하려는 학생들에게 매튜스 학장님께 연락하라고 요청하는 것이에요.","wrong":[null,null,null,null],"kr":{"stem":"학생들은 왜 매튜스 학장님께 연락해야 하나요?","opt":["상을 신청하기 위해","도움을 제공하기 위해","기부를 하기 위해","최신 정보를 제공하기 위해"]}}},"script":[{"sp":"W","text":"Good morning students! The awards ceremony scheduled for Friday at 6pm will now take place in the campus theatre due to a larger turnout than originally anticipated. We are still looking for volunteers to serve as ushers, guide guests through the campus, and set up the refreshments that will be served after the ceremony. If interested, please contact Dean Matthews as soon as possible."}],"kr":{"script":"학생 여러분, 안녕하세요! 금요일 오후 6시로 예정된 시상식은 예상보다 많은 인원이 참석할 것으로 예상되어 이제 교내 극장에서 열릴 예정입니다. 저희는 여전히 안내원(usher)으로 봉사하고, 캠퍼스 내에서 손님들을 안내하며, 시상식 후에 제공될 다과를 준비해 줄 자원봉사자를 찾고 있습니다. 관심 있으신 분은 가능한 한 빨리 매튜스 학장님께 연락해 주십시오."}},"l_d01":{"q":{"l_d01_1":{"a":3,"why":"강연자는 튜바가 명확한 조상 악기가 없다고 말하며, 서펀트와 오피클라이드 같은 악기들이 튜바의 전신으로서 어떻게 발전했는지 설명하고 있어요. 이는 튜바의 전신 악기들의 발달 과정을 추적하는 것이 강연의 주된 목적임을 보여줘요.","wrong":[null,null,null,null],"kr":{"stem":"이 강연의 주된 목적은 무엇입니까?","opt":["대부분의 악기가 왜 빠르게 표준화되었는지 설명하기 위함입니다.","튜바의 모양을 다른 금관악기의 모양과 비교하기 위함입니다.","튜바가 가장 낮은 음을 어떻게 내는지 탐구하기 위함입니다.","튜바의 전신 악기들의 발달 과정을 추적하기 위함입니다."]}},"l_d01_2":{"a":0,"why":"강연자는 \"튜바는 명확한 조상 악기가 없다(the tuba doesn't really have a clear ancestor)\"고 말하면서, 트럼펫과 트롬본 같은 대부분의 금관악기는 \"수세기 동안의 개량을 거쳐 표준화되었다(underwent many centuries of refinement before being standardized)\"고 언급했어요. 이는 트럼펫과 트롬본이 현대 버전으로 이어지는 명확한 조상 악기를 가지고 있다는 점과 대조되는 거예요.","wrong":[null,null,null,null],"kr":{"stem":"트럼펫과 트롬본에 대해 무엇을 추론할 수 있습니까?","opt":["그것들은 현대 버전으로 이어지는 명확한 조상 악기를 가지고 있습니다.","그것들은 종종 금관 이외의 재료로 만들어집니다.","그것들은 아직 표준화된 버전이 없습니다.","그것들은 튜바와 비슷한 방식으로 연주되지 않습니다."]}},"l_d01_3":{"a":1,"why":"강연자는 서펀트에 대해 \"나무 관이 너무 넓어서 음정에 문제가 생겼다(The wooden tube was too wide, which caused problems with intonation)\"고 말했어요. 이는 서펀트의 너비 때문에 정확한 음정으로 연주하기 어려웠다는 것을 의미해요.","wrong":[null,null,null,null],"kr":{"stem":"화자에 따르면, 서펀트의 문제점은 무엇이었습니까?","opt":["그것의 'S'자 모양 때문에 잡기 불편했습니다.","그것의 너비 때문에 음정을 맞추기 어려웠습니다.","그것의 크기 때문에 오케스트라와 함께 연주하기에는 너무 시끄러웠습니다.","그것의 나무 구조 때문에 너무 약했습니다."]}},"l_d01_4":{"a":2,"why":"강연자는 오피클라이드가 서펀트보다 훨씬 인기를 얻었다고 말한 뒤, \"작곡가 베를리오즈는 몇몇 유명한 작품에서 이 악기를 사용했습니다(Berlioz used it in some famous pieces)\"라고 언급했어요. 이는 오피클라이드가 널리 받아들여지고 사용되었음을 보여주는 예시로 사용된 거예요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 작곡가 베를리오즈를 언급합니까?","opt":["오피클라이드의 발명가 중 한 명을 지칭하기 위함입니다.","오피클라이드의 인상적인 음역을 강조하기 위함입니다.","오피클라이드의 폭넓은 수용을 설명하기 위함입니다.","금관으로 만들어진 악기의 단점을 소개하기 위함입니다."]}}},"script":[{"sp":"M","text":"Most wind instruments, which are played by blowing into them, went through lots of modifications before becoming the standardized instruments we see and hear today. Now, most brass instruments, like the trumpet and trombone, underwent many centuries of refinement before being standardized. But the tuba only took about 180 years to reach its current form. That's because, through centuries, composers and inventors wanted an ideal bass instrument to play those really low notes. Rather than tinker with an instrument they didn't love, they'd discard it and start again. So the tuba doesn't really have a clear ancestor, more a series of untyped. An early example was the serpent. The serpent was made of a wooden tube, bent into the shape of, well, a serpent. The letter S. Problem was, it didn't sound great. The wooden tube was too wide, which caused problems with intonation, meaning it was hard to hit the right notes. Imagine a choir of voices accompanied by a serpent, booming along out of tune. Ouch. Well, so long, serpent. And hello, ophiclide. The ophiclide's main advantage was that it was made of brass. The brass construction made its intonation much better. The ophiclide became much more popular than the serpent. The composer Burkard, who was the composer, said, Um, Berlioz used it in some famous pieces. But still, the ophiclide wasn't the answer. Its pitch range was pretty narrow, and composers wanted something that could play lower notes."}],"kr":{"script":"대부분의 관악기(wind instruments)는 불어서 연주하는 악기인데, 오늘날 우리가 보고 듣는 표준화된 악기가 되기까지 많은 수정을 거쳤습니다. 트럼펫과 트롬본 같은 대부분의 금관악기(brass instruments)는 표준화되기까지 수세기 동안의 개량을 거쳤습니다. 하지만 튜바는 현재의 형태에 도달하는 데 약 180년밖에 걸리지 않았습니다. 그 이유는 수세기 동안 작곡가와 발명가들이 정말 낮은 음을 연주할 이상적인 저음 악기(bass instrument)를 원했기 때문입니다. 그들은 마음에 들지 않는 악기를 고치기보다는 버리고 다시 시작하곤 했습니다. 그래서 튜바는 명확한 조상 악기가 있다기보다는, 일련의 다양한 악기들이 있었습니다. 초기 예시 중 하나는 서펀트(serpent)였습니다. 서펀트는 나무 관으로 만들어졌는데, 음, 뱀 모양으로 구부러져 있었습니다. 문자 S자 모양이었죠. 문제는 소리가 좋지 않았다는 것입니다. 나무 관이 너무 넓어서 음정(intonation)에 문제가 생겼는데, 이는 정확한 음을 내기 어려웠다는 것을 의미합니다. 합창단이 서펀트의 반주에 맞춰 연주하는데, 음정이 맞지 않아 쿵쿵거리는 소리가 난다고 상상해 보세요. 끔찍하죠. 음, 서펀트는 이제 안녕입니다. 그리고 오피클라이드(ophiclide)가 등장했습니다. 오피클라이드의 주요 장점은 금관으로 만들어졌다는 것이었습니다. 금관 구조 덕분에 음정이 훨씬 좋아졌습니다. 오피클라이드는 서펀트보다 훨씬 더 인기를 얻었습니다. 작곡가 베를리오즈(Berlioz)는 몇몇 유명한 작품에서 이 악기를 사용했습니다. 하지만 여전히 오피클라이드가 해답은 아니었습니다. 음역(pitch range)이 상당히 좁았고, 작곡가들은 더 낮은 음을 연주할 수 있는 악기를 원했습니다."}},"l_a09":{"q":{"l_a09_1":{"a":2,"why":"질문은 '카페 지금 열었나요?'라고 물어보고 있어요. '닫았어요'는 카페가 열려 있지 않다는 것을 직접적으로 나타내므로, 질문에 대한 적절한 대답이 돼요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["뒤편에 있어요.","커피와 차요.","닫았어요.","그녀는 시간이 돼요."]}}},"script":[{"sp":"W","text":"Is the cafe open now?"}],"kr":{"script":"카페 지금 열었나요?"}},"l_a10":{"q":{"l_a10_1":{"a":0,"why":"화자가 \"세미나에 참석했어요?\"라고 질문했어요. \"늦잠을 잤어요.\"라는 답변은 늦잠을 자서 세미나에 참석하지 못했다는 의미를 내포하고 있어요. 따라서 세미나 참석 여부에 대한 간접적인 이유를 설명하는 적절한 답변이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["늦잠을 잤어요.","아니요, 별로 좋지 않았어요.","교수님께 여쭤봤어요?","확인하는 것을 잊었어요."]}}},"script":[{"sp":"M","text":"Did you attend the seminar?"}],"kr":{"script":"세미나에 참석했어요?"}},"l_a11":{"q":{"l_a11_1":{"a":0,"why":"질문은 '도서관이 지금 열려 있나요?'라고 물어보고 있어요. 0번 선택지는 '네, 저녁 9시까지요.'라고 답하며 도서관이 열려 있는지 여부와 운영 시간을 직접적으로 알려주고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["네, 저녁 9시까지요.","아마 지난주에요.","모든 책이요.","아니요, 저녁 식사는 8시에요."]}}},"script":[{"sp":"W","text":"Is the library open now?"}],"kr":{"script":"도서관이 지금 열려 있나요?"}},"l_a12":{"q":{"l_a12_1":{"a":0,"why":"질문은 쇼가 언제 시작하는지 묻고 있어요. 정답인 \"한 시간쯤 후에요\"는 쇼가 시작하는 시점을 직접적으로 알려주고 있기 때문에 올바른 답변이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["한 시간쯤 후에요.","지역 오케스트라요.","캠퍼스 극장에서요.","학생들에게는 무료예요."]}}},"script":[{"sp":"M","text":"When does the show start?"}],"kr":{"script":"쇼는 언제 시작해요?"}},"l_a13":{"q":{"l_a13_1":{"a":3,"why":"화자가 '제가 필요하시면, 그냥 문자하세요'라고 말했어요. 이 말은 화자가 도움을 주거나 질문에 답해줄 준비가 되어 있다는 것을 의미해요. 3번 선택지인 '질문이 많으시네요, 그렇죠?'는 상대방이 화자를 필요로 할 수 있는 주된 이유, 즉 질문이 많다는 점을 직접적으로 언급하고 있어요. 이는 화자의 도움 제안을 자연스럽게 받아들이는 대화 방식이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["제가 그것을 도와드릴 수 있어요.","더 이상의 정보는 필요 없어요.","질문이 많으시네요, 그렇죠?","아직 저에게 전화번호를 주지 않으셨어요."]}}},"script":[{"sp":"W","text":"If you need me, just text."}],"kr":{"script":"제가 필요하시면, 그냥 문자하세요."}},"l_a14":{"q":{"l_a14_1":{"a":1,"why":"“무엇을 도와드릴까요?”라는 질문은 도움을 제안하는 말이에요. “역사 발표 준비할 게 아직 많아요”라는 답변은 현재 바쁘거나 어려움을 겪고 있는 상황을 설명하며, 도움을 요청하는 이유가 될 수 있어요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["기꺼이 해드리겠습니다.","역사 발표 준비할 게 아직 많아요.","네, 나중에 할 수 있어요.","제 지도 교수님께서 많이 도와주셨어요."]}}},"script":[{"sp":"M","text":"What can I help you with?"}],"kr":{"script":"무엇을 도와드릴까요?"}},"l_a15":{"q":{"l_a15_1":{"a":0,"why":"스크립트에서 '체육관이 왜 문을 닫았나요?'라고 질문하고 있어요. 0번 선택지 '어제 폭풍으로 피해가 발생했어요.'는 체육관이 문을 닫은 이유를 직접적으로 설명해주기 때문에 정답이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["어제 폭풍으로 피해가 발생했어요.","장비를 꼭 꺼야 해요.","새로운 운동 루틴이에요.","그가 이미 두 개를 가지고 있기 때문이에요."]}}},"script":[{"sp":"W","text":"Why is the gym closed?"}],"kr":{"script":"체육관이 왜 문을 닫았나요?"}},"l_b03":{"q":{"l_b03_1":{"a":3,"why":"여자는 \"안내 세션(guided sessions)은 따라하기 쉬워\"라고 말했어요. 이 부분에서 여자가 안내 세션을 가장 좋아한다는 것을 알 수 있어요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 앱의 어떤 기능을 가장 좋아하나요?","opt":["진행 표시줄","매일 알림","채팅","안내 세션"]}},"l_b03_2":{"a":0,"why":"여자는 \"스트레스가 덜해졌어. 그게 핵심이지. 내 삶에서 스트레스를 좀 줄일 수 있으면 좋겠어\"라고 말했어요. 이 발언을 통해 여자가 스트레스 관리를 위해 앱을 사용했다는 것을 알 수 있어요.","wrong":[null,null,null,null],"kr":{"stem":"여자가 앱을 사용해 본 가장 가능성 높은 이유는 무엇인가요?","opt":["스트레스를 관리하기 위해","일정을 공유하기 위해","영적인 지도를 찾기 위해","새로운 사람들을 만나기 위해"]}}},"script":[{"sp":"M","text":"Hey, have you tried that new meditation app?"},{"sp":"W","text":"Yep, it's been about a week now, and I feel less stressed, which is the point."},{"sp":"M","text":"I could use a little less stress in my life. What else is good about this app?"},{"sp":"W","text":"Hmm. The guided sessions are easy to follow. The daily reminders are a bit annoying though."},{"sp":"M","text":"I'll go ahead and give it a try."}],"kr":{"script":"야, 그 새로운 명상 앱 사용해 봤어? 응, 지금 한 일주일 정도 됐는데, 스트레스가 덜해졌어. 그게 핵심이지. 내 삶에서 스트레스를 좀 줄일 수 있으면 좋겠어. 이 앱의 또 다른 좋은 점은 뭐야? 음. 안내 세션(guided sessions)은 따라하기 쉬워. 하지만 매일 알림(daily reminders)은 좀 귀찮아. 나도 한번 사용해 볼게."}},"l_b04":{"q":{"l_b04_1":{"a":1,"why":"여자가 \"이번 주말에 공예 박람회에 가세요?\"라고 물어보고, 남자가 \"네, 저는 수공예품과 독특한 공예품을 구경하는 것을 정말 좋아해요\"라고 대답하며 공예 박람회에 대해 이야기하고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"화자들이 어떤 행사에 대해 이야기하고 있나요?","opt":["음악 콘서트","공예 박람회","음식 축제","도서 박람회"]}},"l_b04_2":{"a":1,"why":"남자가 \"가족을 위한 좋은 선물을 몇 가지 찾고 싶어요\"라고 직접적으로 말하고 있어요. 따라서 남자는 가족을 위한 선물을 찾기를 바라고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"남자는 행사에서 무엇을 찾기를 바라나요?","opt":["집을 위한 미술품","가족을 위한 선물","음식과 음료","옷과 액세서리"]}}},"script":[{"sp":"M","text":"Are you going to the craft fair this weekend?"},{"sp":"W","text":"Yes, I love looking at handmade items and unique crafts."},{"sp":"M","text":"Me too. I'm hoping to find some nice gifts for my family."},{"sp":"W","text":"That's a good idea. I've heard there will be a lot of local artists there."},{"sp":"M","text":"Great. Let's meet up there around 10 am."}],"kr":{"script":"이번 주말에 공예 박람회에 가세요? 네, 저는 수공예품과 독특한 공예품을 구경하는 것을 정말 좋아해요. 저도요. 가족을 위한 좋은 선물을 몇 가지 찾고 싶어요. 좋은 생각이네요. 그곳에 지역 예술가들이 많이 올 거라고 들었어요. 좋아요. 오전 10시쯤 거기서 만나요."}},"l_c03":{"q":{"l_c03_1":{"a":2,"why":"화자는 \"저희는 대학의 연례 채용 박람회(job fair)가 다음 주 수요일... 열릴 예정임을 기쁜 마음으로 알려드립니다\"라고 말하고 있어요. 이는 공지의 주요 내용이 다가오는 채용 박람회임을 명확히 보여주고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"이 공지의 주요 내용은 무엇인가요?","opt":["네트워킹 행사","새로운 직업 워크숍","다가오는 채용 박람회","행사 장소 변경"]}},"l_c03_2":{"a":3,"why":"화자는 공지 마지막에 \"그곳에서 여러분을 뵙기를 바랍니다!\"라고 말하고 있어요. 여기서 '그곳'은 앞서 언급된 채용 박람회를 의미하므로, 화자는 청자들이 채용 박람회에 참석하기를 바라고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 청자들이 무엇을 하기를 바라나요?","opt":["진로 센터를 방문하기","면접을 준비하기","이력서를 제출하기","채용 박람회에 참석하기"]}}},"script":[{"sp":"M","text":"Attention everyone! We are excited to announce that the university's annual job fair will take place next Wednesday from 10 am to 4 pm in the main hall. This is a great opportunity to meet potential employers and explore career options. We hope to see you there!"}],"kr":{"script":"여러분, 주목해 주세요! 저희는 대학의 연례 채용 박람회(job fair)가 다음 주 수요일 오전 10시부터 오후 4시까지 본관에서 열릴 예정임을 기쁜 마음으로 알려드립니다. 이것은 잠재적인 고용주들을 만나고 직업 선택지를 탐색할 수 있는 좋은 기회예요. 그곳에서 여러분을 뵙기를 바랍니다!"}},"l_c04":{"q":{"l_c04_1":{"a":2,"why":"스크립트에서 '돈을 벌 방법', '유연한 근무 일정', '현장 면접', '직원 할인'과 같은 표현들이 언급되어 있어요. 이러한 내용들은 모두 일자리를 구하는 것에 대한 정보를 제공하고 있음을 보여주고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"이 공지는 주로 무엇에 관한 것인가요?","opt":["매장 개점","재정 세미나","구직 기회","변경된 일정"]}},"l_c04_2":{"a":3,"why":"스크립트에서 커피 머그는 '학교에 대한 애정을 보여주기 좋아하는 동문들에게 가장 인기 있는 기념품(top picks for alumni who love to show their school spirit)'이라고 언급하고 있어요. 이는 커피 머그가 인기 있는 대학교 기념품이라는 것을 나타내고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 커피 머그에 대해 무엇을 언급하고 있나요?","opt":["디자인 때문에 매우 실용적이에요.","오전 10시 이전에는 구매할 수 없을 거예요.","책을 구매하면 무료로 제공돼요.","인기 있는 대학교 기념품이에요."]}}},"script":[{"sp":"W","text":"Looking for a way to earn some cash but need flexible scheduling? At the campus bookstore we get it. Stop by this Saturday from 10am to 2pm for an on the spot interview with one of our managers. Along with flexible hours you'll get employee discounts on books, gear and favourite souvenirs like our University Coffee Mugs which are top picks for alumni who love to show their school spirit."}],"kr":{"script":"돈을 벌 방법을 찾고 있지만 유연한 근무 일정이 필요하신가요? 캠퍼스 서점에서 저희는 그 마음을 잘 알아요. 이번 주 토요일 오전 10시부터 오후 2시 사이에 들러서 저희 매니저 중 한 명과 현장 면접을 보세요. 유연한 근무 시간과 함께, 책, 용품, 그리고 학교에 대한 애정을 보여주기 좋아하는 동문들에게 가장 인기 있는 기념품인 저희 대학교 커피 머그 같은 인기 기념품에 대한 직원 할인을 받으실 수 있어요."}},"l_a16":{"q":{"l_a16_1":{"a":3,"why":"질문은 수요일 수업을 위해 보통 몇 시에 일어나는지 묻고 있어요. '오전 7시쯤이요'는 이 질문에 직접적으로 시간을 알려주는 답변이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["어제 늦게 일어났어요.","매일 밤 알람을 맞춰요.","일찍 일어나는 건 어려워요.","오전 7시쯤이요."]}}},"script":[{"sp":"M","text":"When do you usually wake up for Wednesday classes?"}],"kr":{"script":"수요일 수업을 위해 보통 몇 시에 일어나세요?"}},"l_a17":{"q":{"l_a17_1":{"a":1,"why":"질문은 가구가 도착하는 데 얼마나 걸리는지 묻고 있어요. '이사 업체가 늦어졌어요'라는 답변은 가구 도착 시간에 영향을 미치는 구체적인 이유를 제시하고 있어서 가장 적절한 응답이에요. 이 답변은 가구 도착이 지연될 수 있음을 암시하고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["소파가 정말 편안해요.","이사 업체가 늦어졌어요.","책상은 길이가 1.5미터예요.","저희는 부엌을 리모델링하고 있어요."]}}},"script":[{"sp":"W","text":"How long before the furniture arrives?"}],"kr":{"script":"가구가 도착하려면 얼마나 걸리나요?"}},"l_a18":{"q":{"l_a18_1":{"a":1,"why":"스크립트에서 \"캠퍼스 정원이 가을에 정말 예뻐 보여요\"라고 말하고 있어요. 이 말은 정원에 있는 식물들이 아름답다는 것을 의미하기 때문에, 2번 보기가 정답이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["너무 바빠서 그걸 못 했어요.","식물들이 아름다워요.","오후 4시에 시작해요.","수업에 서둘러 가야겠어요."]}}},"script":[{"sp":"M","text":"The campus garden looks lovely in autumn."}],"kr":{"script":"캠퍼스 정원이 가을에 정말 예뻐 보여요."}},"l_b05":{"q":{"l_b05_1":{"a":3,"why":"남자는 초콜릿 무스 케이크에 대해 \"그건 제 파티에서 항상 인기 만점이었거든요\"라고 말했어요. 이 말은 그 케이크가 파티에서 늘 성공적이었다는 의미로, 인기 있는 품목이었다는 것을 나타내요.","wrong":[null,null,null,null],"kr":{"stem":"남자는 초콜릿 무스 케이크에 대해 뭐라고 말하나요?","opt":["매진되었어요.","새로운 주방장이 만들었어요.","최근에 가격이 올랐어요.","인기 있는 품목이었어요."]}},"l_b05_2":{"a":1,"why":"여자는 \"제 손님들 중 몇 분은 디저트에 대해 까다로우세요. 그리고 한 분은 제가 뭘 내놓을지 벌써 물어봤어요\"라고 말했어요. 이 언급은 그녀가 손님들의 취향 때문에 디저트 선택에 신중해야 하는 이유를 설명해 줘요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 왜 손님들을 언급하나요?","opt":["손님 중 한 명이 디저트를 가져올 것이라고 제안하기 위해서","디저트 선택에 신중한 이유를 보여주기 위해서","손님 중 한 명에게 케이크 레시피를 받았다고 언급하기 위해서","빵집에 대해 어디서 들었는지 설명하기 위해서"]}}},"script":[{"sp":"W","text":"I'm planning a dinner party and need to find a good bakery for desserts."},{"sp":"M","text":"Have you tried buttercup lane on Sargent Street?"},{"sp":"W","text":"I have, but it was disappointing. Smaller portions, higher prices and not as tasty."},{"sp":"M","text":"Did they get a new chef or change owners?"},{"sp":"W","text":"Not that I know of, but they've replaced some long time favorites."},{"sp":"M","text":"Like no more chocolate mousse cake. It was always a hit at my parties."},{"sp":"W","text":"That's too bad. A couple of my guests are picky about desserts. And one already asked what I'm serving. I'll need to keep looking."}],"kr":{"script":"저녁 파티를 계획 중인데 디저트용으로 좋은 빵집을 찾아야 해요. Sargent Street에 있는 Buttercup Lane에 가본 적 있어요? 가봤는데 실망스러웠어요. 양은 더 적고, 가격은 더 비싸고 맛도 예전 같지 않더라고요. 새로운 주방장이 왔거나 주인이 바뀌었나요? 제가 알기로는 아니지만, 오랫동안 인기 있었던 메뉴 몇 가지를 바꿨더라고요. 예를 들어, 초콜릿 무스 케이크는 더 이상 없어요. 그건 제 파티에서 항상 인기 만점이었거든요. 정말 안됐네요. 제 손님들 중 몇 분은 디저트에 대해 까다로우세요. 그리고 한 분은 제가 뭘 내놓을지 벌써 물어봤어요. 계속 찾아봐야겠어요."}},"l_b06":{"q":{"l_b06_1":{"a":3,"why":"여자는 \"제가 직접 정원을 가꾸기 시작해서 허브와 채소를 키우는 모든 것을 알아야 해요\"라고 말했어요. 이 말은 그녀가 콘서트 대신 원예 워크숍에 참석한 이유가 자신에게 중요했음을 직접적으로 설명해 주고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 왜 자신의 새 정원에 대해 언급하나요?","opt":["남자에게 허브와 채소를 주려고요.","남자가 대학 센터에 방문해야 한다고 암시하려고요.","그녀가 내일 오후에 공원에 갈 수 없다는 것을 나타내려고요.","워크숍에 참석하는 것이 그녀에게 왜 중요했는지 설명하려고요."]}},"l_b06_2":{"a":3,"why":"남자는 \"공원의 음향(acoustics)이 별로 좋지 않아서 음질이 다소 평범했고 노래에 대한 제값을 못 했어요\"라고 말했어요. 이 말은 공원의 음향 시설이 좋지 않아 콘서트 장소로 적합하지 않았음을 암시하고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"남자는 록 콘서트에 대해 무엇을 암시하나요?","opt":["매우 즐거웠다고요.","주로 평범한 음악가들이 출연했다고요.","남자가 가장 좋아하는 노래들이 포함되지 않았다고요.","부적절한 장소에서 열렸다고요."]}}},"script":[{"sp":"M","text":"Did you go to the rock concert in the park yesterday afternoon?"},{"sp":"W","text":"I went to a gardening workshop at the university center instead. It's sad that I missed out on the concert, but I'm starting my own garden, and I need to know all the ins and outs of growing herbs and vegetables."},{"sp":"M","text":"Nice, and to be honest, you didn't miss that much."},{"sp":"W","text":"No?"},{"sp":"M","text":"Well, I love some of the songs they played, but the acoustics in the park aren't very good, so the sound quality was rather mediocre and didn't do justice to the songs."}],"kr":{"script":"어제 오후에 공원에서 록 콘서트에 갔어요? 저는 대신 대학 센터에서 원예 워크숍에 갔어요. 콘서트를 놓쳐서 아쉽지만, 제가 직접 정원을 가꾸기 시작해서 허브와 채소를 키우는 모든 것을 알아야 해요. 잘됐네요, 그리고 솔직히 말하면, 그렇게 많이 놓친 건 아니에요. 그래요? 음, 저는 그들이 연주한 노래들 중 몇 곡을 좋아하지만, 공원의 음향(acoustics)이 별로 좋지 않아서 음질이 다소 평범했고 노래에 대한 제값을 못 했어요."}},"l_d02":{"q":{"l_d02_1":{"a":2,"why":"스크립트에서 \"이 개념은 1957년 심리학자 레온 페스팅거(Leon Festinger)에 의해 소개되었습니다\"라고 언급하고 있어요. 또한 \"페스팅거에 따르면, 사람들은 자신의 신념이나 행동을 변화시켜 이러한 불편함을 줄이려는 동기를 가집니다\"라고 설명하며, 그가 인지 부조화 개념을 소개하고 그것이 인간의 신념과 행동에 미치는 영향을 설명했음을 알 수 있어요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 레온 페스팅거에 대해 무엇이라고 말합니까?","opt":["그는 잘 알려진 심리학 개념을 마케팅 캠페인에 도입했습니다.","그는 어린 나이에 인지 부조화를 경험했습니다.","그는 정신적 갈등이 인간의 신념이나 행동에 어떻게 영향을 미칠 수 있는지 처음으로 설명했습니다.","그는 사람들이 인지 부조화를 피하는 방법에 대해 교육하는 데 중점을 두었습니다."]}},"l_d02_2":{"a":3,"why":"스크립트에서 \"이러한 동기는 제품 마케팅에 활용될 수 있습니다\"라고 말한 뒤, 휘발유 자동차와 전기 자동차의 예를 들어 설명하고 있어요. 이는 인지 부조화가 마케팅 캠페인에서 어떻게 활용될 수 있는지 보여주는 구체적인 예시예요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 휘발유 자동차와 전기 자동차에 대해 논합니까?","opt":["심리학자와 환경 과학자 간의 협력을 강조하기 위해서입니다.","깨끗한 환경이 정신 건강을 지지할 수 있음을 보여주기 위해서입니다.","인지 부조화 개념의 문제점을 파악하기 위해서입니다.","인지 부조화가 제품 광고에 어떻게 유용할 수 있는지 설명하기 위해서입니다."]}},"l_d02_3":{"a":3,"why":"스크립트에서 \"인지 부조화는 비판적 사고를 장려할 수 있기 때문에 교육에서도 유용할 수 있습니다\"라고 언급한 후, 미국 혁명에 대한 학생의 신념과 교사의 새로운 증거 제시를 예로 들고 있어요. 이는 인지 부조화가 학습 과정에서 어떻게 작용하여 비판적 사고와 정보 탐색을 유도하는지 보여주는 예시예요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 1700년대의 역사적 사건을 논합니까?","opt":["미국에서 인지 부조화 이론의 발달에 대한 세부 정보를 제공하기 위해서입니다.","인지 부조화가 경제적 결과를 초래할 수 있다는 생각을 지지하기 위해서입니다.","인지 부조화가 어떻게 주요 역사적 사건으로 이어질 수 있는지 보여주기 위해서입니다.","인지 부조화가 어떻게 학습을 장려할 수 있는지 설명하기 위해서입니다."]}},"l_d02_4":{"a":0,"why":"스크립트에서 화자는 인지 부조화가 \"제품 마케팅에 활용될 수 있습니다\"라고 말하고, \"교육에서도 유용할 수 있습니다\"라고 언급하며, 마지막으로 \"긍정적인 행동 변화를 촉진하는 데 도움이 될 수 있습니다\"라고 결론 내리고 있어요. 이러한 언급들은 인지 부조화가 긍정적인 결과를 가져올 수 있음을 시사하고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"화자의 인지 부조화에 대한 태도는 어떻습니까?","opt":["그녀는 때때로 유익할 수 있다고 생각합니다.","그녀는 그것이 유발할 수 있는 정신적 불편함에 대해 우려합니다.","그녀는 일부 사람들이 그것을 오해할까 봐 두려워합니다.","그녀는 미래에 그것의 사례가 더 흔해질 수 있다고 생각합니다."]}}},"script":[{"sp":"W","text":"Cognitive dissonance is a term that describes the mental discomfort a person experiences due to contradictory behaviors or beliefs. The concept was introduced by psychologist Leon Festinger in 1957. According to Festinger, people are motivated to reduce this discomfort by changing their beliefs or behaviors. This motivation can be used in product marketing. If a consumer is worried about the environmental impact of gasoline cars but still drives one, this could cause cognitive dissonance. A marketing campaign for electric vehicles could take advantage of this by highlighting the harm done by gasoline cars and so increase the dissonance. Then electric cars can be implicitly touted as a way of resolving the mental conflict. Cognitive dissonance can also be useful in education because it can encourage critical thinking. Say that a student believes that the American Revolution in the 1700s was driven only by a desire for independence from British rule. Then a teacher might present evidence that economic factors, like taxation and trade restrictions, also played a role. The resulting mental discomfort might stimulate the student to start questioning their initial belief and to seek more information on the subject. Understanding cognitive dissonance can help us promote positive behavioral change."}],"kr":{"script":"인지 부조화(cognitive dissonance)는 개인이 모순되는 행동이나 신념으로 인해 경험하는 정신적 불편함을 설명하는 용어입니다. 이 개념은 1957년 심리학자 레온 페스팅거(Leon Festinger)에 의해 소개되었습니다. 페스팅거에 따르면, 사람들은 자신의 신념이나 행동을 변화시켜 이러한 불편함을 줄이려는 동기를 가집니다. 이러한 동기는 제품 마케팅에 활용될 수 있습니다. 만약 소비자가 휘발유 자동차의 환경적 영향에 대해 걱정하면서도 여전히 휘발유 자동차를 운전한다면, 이는 인지 부조화를 유발할 수 있습니다. 전기 자동차 마케팅 캠페인은 휘발유 자동차가 환경에 미치는 해악을 강조하여 이러한 부조화를 증가시킴으로써 이를 활용할 수 있습니다. 그러면 전기 자동차는 정신적 갈등을 해결하는 방법으로 암묵적으로 홍보될 수 있습니다. 인지 부조화는 비판적 사고를 장려할 수 있기 때문에 교육에서도 유용할 수 있습니다. 예를 들어, 한 학생이 1700년대 미국 혁명이 오직 영국 지배로부터의 독립 열망에 의해서만 추진되었다고 믿는다고 가정해 봅시다. 그때 교사는 세금과 무역 제한 같은 경제적 요인들도 역할을 했다는 증거를 제시할 수 있습니다. 그 결과로 발생하는 정신적 불편함은 학생이 자신의 초기 신념에 의문을 제기하고 해당 주제에 대한 더 많은 정보를 찾도록 자극할 수 있습니다. 인지 부조화를 이해하는 것은 긍정적인 행동 변화를 촉진하는 데 도움이 될 수 있습니다."}},"l_d03":{"q":{"l_d03_1":{"a":2,"why":"강연은 행동 경제학이 무엇인지 소개하고, 손실 회피, 현재 편향, 확증 편향과 같은 여러 주요 개념들을 설명하고 있어요. 이 개념들은 모두 행동 경제학의 핵심적인 부분들이에요.","wrong":[null,null,null,null],"kr":{"stem":"이 강연의 주요 주제는 무엇입니까?","opt":["전통적인 경제 이론","재정적 손실을 피하는 방법","행동 경제학의 주요 개념","인지 편향이 정책 결정에 미치는 영향"]}},"l_d03_2":{"a":1,"why":"강연에서 \"손실 회피는 위험 회피 행동으로 이어질 수 있습니다\"라고 명시적으로 언급하고 있어요. 또한 \"손실의 위험은 이득을 얻을 동등하거나 더 큰 기회가 있을 때조차도 참을 수 없는 것처럼 보입니다\"라고 설명하고 있어요.","wrong":[null,null,null,null],"kr":{"stem":"강연에 따르면, 손실 회피는 무엇으로 이어집니까?","opt":["이득을 얻는 것에 대한 선호","위험을 피하는 경향","합리적인 의사 결정","효용 극대화 증가"]}},"l_d03_3":{"a":2,"why":"화자는 현재 편향을 설명하면서 \"이는 은퇴를 위해 저축하는 것을 어렵게 만들고 사람들이 과소비하게 만들 수 있습니다\"라고 말하고 있어요. 은퇴 저축은 현재의 만족보다 미래의 이점을 중요하게 여기는 것과 관련된 현재 편향의 예시예요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 은퇴를 위한 저축을 언급합니까?","opt":["손실 회피 개념을 설명하기 위해","확증 편향을 설명하기 위해","현재 편향의 효과를 보여주기 위해","합리적인 행동의 예를 제공하기 위해"]}},"l_d03_4":{"a":2,"why":"강연에서는 확증 편향을 \"개인이 기존의 믿음을 확인시켜주는 정보를 선호하고 모순되는 데이터는 무시하는 것\"이라고 설명하고 있어요. 선호하는 브랜드에 대한 긍정적인 리뷰만 찾는 것은 이러한 정의에 정확히 부합하는 행동이에요.","wrong":[null,null,null,null],"kr":{"stem":"확증 편향을 겪는 사람을 가장 잘 설명하는 행동은 무엇입니까?","opt":["최근 할인된 가격으로 제품을 구매하는 것","제품에 대한 객관적인 비교를 찾는 것","선호하는 브랜드에 대한 긍정적인 리뷰를 찾는 것","특정 제품에서 신뢰성보다 저렴한 비용을 선택하는 것"]}}},"script":[{"sp":"M","text":"Today, we're discussing behavioral economics, a fascinating field that explores how psychological factors influence economic decision-making. Traditionally, economists assumed that individuals made rational choices. However, behavioral economics challenges this notion by demonstrating that people often behave irrationally because of cognitive biases and emotions. One classic example is the concept of loss aversion. Studies show that individuals tend to prefer avoiding losses rather than acquiring equivalent gains. For instance, losing 100 euros feels worse than gaining 100 euros feels good. This bias can lead to risk-averse behavior. This bias can lead to risk-averse behavior impacting consumer decisions. The risk of loss seems intolerable even when there is an equal or greater opportunity for gain. Another factor is present bias, where individuals disproportionately value immediate rewards over future benefits. This can make it hard to save for retirement and can lead people to overspend. Another behavior that economists examine is conformism. This is a form of conformism bias, where individuals favor information that confirms their pre-existing beliefs while disregarding contradictory data. Imagine a consumer who strongly believes that Brand X makes the best smartphones. Because of the conformism bias, they might only seek out favorable reviews about Brand X while ignoring negative ones. Even when presented with objective comparisons showing that another brand has better performance, features, or is more reliable, they will downplay that information."}],"kr":{"script":"오늘 저희는 행동 경제학(behavioral economics)에 대해 논의할 것입니다. 행동 경제학은 심리적 요인이 경제적 의사 결정에 어떻게 영향을 미치는지 탐구하는 흥미로운 분야입니다. 전통적으로 경제학자들은 개인이 합리적인 선택을 한다고 가정했습니다. 그러나 행동 경제학은 인지 편향(cognitive biases)과 감정 때문에 사람들이 종종 비합리적으로 행동한다는 것을 보여줌으로써 이러한 개념에 이의를 제기합니다. 한 가지 고전적인 예는 손실 회피(loss aversion) 개념입니다. 연구에 따르면 개인은 동등한 이득을 얻는 것보다 손실을 피하는 것을 선호하는 경향이 있습니다. 예를 들어, 100유로를 잃는 것은 100유로를 얻는 것보다 더 나쁘게 느껴집니다. 이러한 편향은 위험 회피 행동으로 이어질 수 있습니다. 이 편향은 소비자 결정에 영향을 미치는 위험 회피 행동으로 이어질 수 있습니다. 손실의 위험은 이득을 얻을 동등하거나 더 큰 기회가 있을 때조차도 참을 수 없는 것처럼 보입니다. 또 다른 요인은 현재 편향(present bias)인데, 이는 개인이 미래의 이점보다 즉각적인 보상을 불균형적으로 중요하게 여기는 것입니다. 이는 은퇴를 위해 저축하는 것을 어렵게 만들고 사람들이 과소비하게 만들 수 있습니다. 경제학자들이 조사하는 또 다른 행동은 확증 편향(confirmation bias)입니다. 이것은 개인이 기존의 믿음을 확인시켜주는 정보를 선호하고 모순되는 데이터는 무시하는 확증 편향의 한 형태입니다. Brand X가 최고의 스마트폰을 만든다고 굳게 믿는 소비자를 상상해 보십시오. 확증 편향 때문에 그들은 Brand X에 대한 긍정적인 리뷰만 찾고 부정적인 리뷰는 무시할 수 있습니다. 다른 브랜드가 더 나은 성능, 기능 또는 더 높은 신뢰성을 가지고 있음을 보여주는 객관적인 비교가 제시될 때조차도 그들은 그 정보를 경시할 것입니다."}},"w_bas_01":{"items":[{"id":"w_bas_01_1","solution":["I","chose","the one","my","mom","liked"],"answer":"I chose the one my mom liked."},{"id":"w_bas_01_2","solution":["where","did","the manager","put","the","extra","keys"],"answer":"Where did the manager put the extra keys?"},{"id":"w_bas_01_3","solution":["nobody","knows","why","the","new policy","was","cancelled"],"answer":"Nobody knows why the new policy was cancelled."},{"id":"w_bas_01_4","solution":["gave","a","short","quiz","to","the class"],"answer":"The teacher gave a short quiz to the class."},{"id":"w_bas_01_5","solution":["have","to finish","the","monthly","report","before","lunch"],"answer":"They have to finish the monthly report before lunch."},{"id":"w_bas_01_6","solution":["is","the","most","expensive","of","all","the current ones"],"answer":"This laptop is the most expensive of all the current ones."},{"id":"w_bas_01_7","solution":["so","does","everyone","else","here"],"answer":"So does everyone else here."},{"id":"w_bas_01_8","solution":["our","team","has","made","a lot","of","progress"],"answer":"Our team has made a lot of progress."},{"id":"w_bas_01_9","solution":["was","sent","to","every","member","of","the staff"],"answer":"The email was sent to every member of the staff."},{"id":"w_bas_01_10","solution":["should","pay","close","attention","to","the details"],"answer":"You should pay close attention to the details."}],"kr":{"items":[{"prompt_ko":"어느 아파트로 결국 정했어요?","answer_ko":"엄마가 마음에 들어 한 곳으로 골랐어요.","note":"**관계절**로 명사를 꾸며요. **the one** 뒤에 **(that) my mom liked**가 붙어 '엄마가 좋아한 그것'을 나타내요. 목적격 관계대명사 that은 생략돼 «the one + 주어 + 동사» 형태가 돼요."},{"prompt_ko":"지금 창고에 못 들어가겠어요.","answer_ko":"매니저가 여분 열쇠를 어디에 뒀나요?","note":"**직접 의문문(Wh-)** 이에요. **Where + did + 주어 + 동사원형(put)** 순서로, 과거라 did를 쓰고 동사는 원형으로 돌아가요."},{"prompt_ko":"규칙 변경에 대해 설명해 준 적 있어요?","answer_ko":"새 규정이 왜 취소됐는지 아무도 몰라요.","note":"**간접의문문**이에요. knows 뒤에 **why + 주어 + 동사**가 평서문 어순으로 들어가요(why the new policy was cancelled). 여기에 **수동태(was cancelled)**가 겹쳐 있어요."},{"prompt_ko":"오늘 아침에 왜 다들 이렇게 긴장한 표정이에요?","answer_ko":"선생님이 반에 짧은 쪽지시험을 냈어요.","note":"**수여동사 give**의 3형식 변형이에요. **give + 사물(a short quiz) + to + 사람(the class)** 순서로, 사람을 뒤로 뺄 땐 **to**를 붙여요."},{"prompt_ko":"팀은 마감을 어떻게 맞출 계획인가요?","answer_ko":"그들은 점심 전에 월간 보고서를 끝내야 해요.","note":"**have to + 동사원형** 구조예요. '~해야 한다'는 의무를 나타내고 **have to finish**로 이어져요. **before lunch**(점심 전에)로 시점을 붙여요."},{"prompt_ko":"최근에 컴퓨터를 바꿨다고 들었어요.","answer_ko":"이 노트북이 현재 나온 것 중 가장 비싸요.","note":"**최상급(the most + 형용사)** 구조예요. 3음절 이상 형용사는 **the most expensive**로 만들고 범위는 **of all ...**로 나타내요."},{"prompt_ko":"새 일정이 훨씬 낫다고 생각해요.","answer_ko":"여기 다들 그렇게 생각해요.","note":"**So + 동사 + 주어** 도치 구조예요. '~도 그렇다'는 동의를 나타내고, 앞 문장이 일반동사(think) 현재형이라 대동사 **does**를 써서 **So does everyone else**가 돼요."},{"prompt_ko":"요즘 프로젝트는 어떻게 돼 가요?","answer_ko":"우리 팀은 많은 진전을 이뤘어요.","note":"**현재완료(has + p.p.)** 구조예요. **has made**로 '(지금까지) 해냈다'는 결과를 나타내요. **make progress**(진전을 이루다)는 자주 쓰는 표현이에요."},{"prompt_ko":"일정 변경 소식 다들 들었어요?","answer_ko":"그 이메일은 전 직원에게 발송됐어요.","note":"**수동태(be + p.p.)** 구조예요. **The email was sent**로 '이메일이 보내졌다'를 나타내고 받는 대상은 **to** 뒤에 놓아요(to every member of the staff)."},{"prompt_ko":"이 양식에서 자꾸 같은 실수를 해요.","answer_ko":"세부 사항에 세심히 주의를 기울여야 해요.","note":"**조동사 should** 구조예요. **should + 동사원형(pay)**로 조언을 나타내요. **pay attention to**(~에 주의를 기울이다)는 굳어진 표현이라 to를 빠뜨리지 않아요."}]}},"w_em_01":{"model":"","rubric":[],"kr":{"situation_ko":"교수님(오카포 박사님)이 추천서를 써 주신 덕분에 교환학생 프로그램에 합격했어요. 방금 합격 통보를 받았고, 교수님의 지도가 앞으로의 목표에 어떤 영향을 줬는지도 짧게 전하고 싶어요.","directions_ko":["추천서에 대해 감사 인사를 해요.","합격 소식과 그 프로그램이 당신에게 갖는 의미를 전해요.","교수님의 지도가 앞으로의 계획에 어떤 영향을 줬는지 설명해요."]}},"w_ad_01":{"model":"","rubric":[],"kr":{"prof_ko":"우리는 사람들이 제2언어를 어떻게 가장 잘 익히는지 살펴봤어요. 어떤 연구자들은 그 언어를 쓰는 나라에서 사는 '완전 몰입'이 자연스러운 유창성을 만든다고 주장해요. 다른 이들은 교실 수업이 더 튼튼한 장기적 토대를 쌓는다고 봐요. 새 언어를 배우는 데 어느 쪽이 더 낫다고 보나요, 그 이유는요?","posts_ko":[{"name":"Olivia","text_ko":"저는 몰입이 쉽게 이긴다고 봐요. 하루 종일 언어에 둘러싸이면 교재가 못 담는 슬랭, 리듬, 몸짓까지 사람들이 실제로 어떻게 말하는지 배워요. 저는 해외에서 석 달 만에, 몇 년간 수업으로 배운 것보다 더 많은 스페인어를 익혔어요. 계속 써야만 했으니까요."},{"name":"Ethan","text_ko":"몰입만으로는 같은 실수를 몇 년째 반복하는 자신감 넘치는 화자를 만드는 경우가 많아요. 오류를 고쳐 주고 문법을 설명해 줄 교사가 없으면 나쁜 습관이 굳어져요. 교실은 구조와 명확한 진행, 그리고 몰입이 좀처럼 주지 못하는 피드백을 줘요."}]}},"s_lr_01":{"items":[{"n":1,"text":"Here is how to start and adjust the treadmill."},{"n":2,"text":"There are many benches in the weightlifting area."},{"n":3,"text":"We do encourage the use of yoga mats for stretching out."},{"n":4,"text":"The rowing machine is excellent for a full body workout."},{"n":5,"text":"We have plenty of exercise bikes for cardio training."},{"n":6,"text":"Please use the wipes provided at each station for cleaning equipment after use."},{"n":7,"text":"If you want to see great results quickly, consider joining our daily fitness classes."}]},"s_iv_01":{"items":[{"n":1,"text":"Thank you for agreeing to participate. I'd like to ask you some questions about your experiences with volunteering and community service. First, do you ever participate in any volunteer activities? And if you do, how often do you volunteer?"},{"n":2,"text":"Thank you. Can you tell me about a charity effort or a donation drive that you have heard about that made an impact on where you live?"},{"n":3,"text":"Interesting. Can you describe a public service project that you have been involved in or would like to participate in if you had the time?"},{"n":4,"text":"Great. Some people believe that volunteering should be a mandatory part of the school curriculum to help students develop a sense of community. Do you agree or disagree with this idea? Why?"}]}}};
